import{_ as l,o as t,c as e,a5 as i}from"./chunks/framework.CXroN2RO.js";const p=JSON.parse('{"title":"第1章 コンピュータとは何か ── 情報の表現","description":"","frontmatter":{"title":"第1章 コンピュータとは何か ── 情報の表現","study":{"source":"IT教本","kind":"学習ガイド","status":"学習計画・概要","summary":"すべてのゲームデータ ── 座標、HP、テクスチャ、サウンド、セーブデータ ── は 最終的にビット列である。「floatの精度でキャラがガタつく」「色が変」 「セーブデータが壊れた」といった実務のバグは、ビットレベルの表現を"}},"headers":[],"relativePath":"guide/low-level/computer-and-data.md","filePath":"guide/low-level/computer-and-data.md"}'),o={name:"guide/low-level/computer-and-data.md"};function r(n,a,s,d,c,h){return t(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="第1章-コンピュータとは何か-──-情報の表現" tabindex="-1">第1章 コンピュータとは何か ── 情報の表現 <a class="header-anchor" href="#第1章-コンピュータとは何か-──-情報の表現" aria-label="Permalink to &quot;第1章 コンピュータとは何か ── 情報の表現&quot;">​</a></h1><h2 id="学ぶ理由" tabindex="-1">学ぶ理由 <a class="header-anchor" href="#学ぶ理由" aria-label="Permalink to &quot;学ぶ理由&quot;">​</a></h2><p>すべてのゲームデータ ── 座標、HP、テクスチャ、サウンド、セーブデータ ── は 最終的に<strong>ビット列</strong>である。「floatの精度でキャラがガタつく」「色が変」 「セーブデータが壊れた」といった実務のバグは、ビットレベルの表現を 知らないと原因にたどり着けない。ここは全20章の土台の土台。</p><h2 id="到達目標" tabindex="-1">到達目標 <a class="header-anchor" href="#到達目標" aria-label="Permalink to &quot;到達目標&quot;">​</a></h2><ul><li>任意の整数を2進数・16進数で読み書きできる</li><li>2の補数表現を説明でき、<code>(int)-1 == (unsigned)0xFFFFFFFF</code> の理由が分かる</li><li>IEEE 754浮動小数点の構造(符号・指数・仮数)を説明できる</li><li>「floatで0.1が正確に表せない」「大きな座標で精度が落ちる」理由が分かる</li><li>文字コード(ASCII/UTF-8)とエンディアンを説明できる</li></ul><h2 id="前提知識" tabindex="-1">前提知識 <a class="header-anchor" href="#前提知識" aria-label="Permalink to &quot;前提知識&quot;">​</a></h2><p>なし。ここが出発点。</p><h2 id="学ぶ内容" tabindex="-1">学ぶ内容 <a class="header-anchor" href="#学ぶ内容" aria-label="Permalink to &quot;学ぶ内容&quot;">​</a></h2><ol><li><strong>2進数・16進数</strong><ul><li>ビット、バイト、ワード。なぜ16進数を使うか(4bit=1桁でビットと相性が良い)</li><li>ビット演算: AND/OR/XOR/NOT、シフト。フラグ管理 <code>flags |= JUMPING</code></li></ul></li><li><strong>整数の表現</strong><ul><li>符号なし整数、2の補数(なぜ「補数」だと加算器1つで減算もできるのか)</li><li>オーバーフロー: C/C++の符号なし整数は型の範囲で剰余計算される。 符号付き整数の表現範囲を超える算術は未定義動作であり、常に巻き戻るとは限らない</li><li>固定小数点数(昔のゲーム機や、演算の再現性を設計したい場面で使う)。 これを選ぶだけで決定性が保証されるわけではなく、丸め・溢れ・処理順も揃える</li></ul></li><li><strong>浮動小数点 (IEEE 754)</strong><ul><li>本章では一般的なIEEE 754 binary32のfloatを例にする: 符号1 + 指数8 + 格納する仮数部23bit。C/C++の型名だけでこの形式が保証されるわけではない</li><li>精度の偏り: 0付近は細かく、大きくなるほど粗い → <strong>オープンワールドで原点から離れるとアニメがガタつく理由</strong> (対策: カメラ相対レンダリング、ワールドオリジンシフト)</li><li>特殊値: NaN, Inf, -0。NaNは伝染する(<code>NaN != NaN</code> に注意)</li><li>binary64の例では <code>0.1 + 0.2 != 0.3</code> となる。比較方法は用途で選ぶ。 近似一致は値の規模に応じた相対許容誤差と、0付近の絶対許容誤差を検討する。 型のepsilonを全ての値へ固定で当てはめない。厳密一致が必要な場合やNaN/Infも別途扱う</li></ul></li><li><strong>文字と色の表現</strong><ul><li>ASCII、Unicode、UTF-8/UTF-16(WindowsとUEはUTF-16、多くのファイルはUTF-8)</li><li>色: RGBA8888、リニア色空間とsRGB(第12章で再訪)</li></ul></li><li><strong>エンディアン</strong><ul><li>リトル/ビッグエンディアン。x86もARMもGPUも基本リトル</li><li>バイナリファイル(アセット)やネットワークで問題になる</li></ul></li><li><strong>ノイマン型アーキテクチャの概観</strong><ul><li>「プログラムもデータもメモリに置かれ、CPUが命令を1つずつ実行する」</li><li>この1行が以後の全章の前提</li></ul></li></ol><h2 id="重要概念" tabindex="-1">重要概念 <a class="header-anchor" href="#重要概念" aria-label="Permalink to &quot;重要概念&quot;">​</a></h2><ul><li><strong>ビットは意味を持たない。解釈が意味を与える。</strong> 同じ32bitが int にも float にも 色にも 命令にもなる。キャスト・シリアライズ・ 型パンニングの理解はここから。</li><li><strong>2の補数</strong>: 加算回路だけで減算が実現できる天才的表現</li><li><strong>浮動小数点には表現と演算の丸めがある</strong>: 許容できる誤差と、その扱いを設計する</li><li><strong>精度は相対的</strong>: floatは「約7桁の10進有効数字」</li></ul><h2 id="ゲーム開発との関係" tabindex="-1">ゲーム開発との関係 <a class="header-anchor" href="#ゲーム開発との関係" aria-label="Permalink to &quot;ゲーム開発との関係&quot;">​</a></h2><table tabindex="0"><thead><tr><th>現場の事象</th><th>この章の知識</th></tr></thead><tbody><tr><td>ビットフラグでの状態管理</td><td>ビット演算</td></tr><tr><td>座標が大きいと物理・アニメが暴れる</td><td>floatの相対精度</td></tr><tr><td>リプレイ再現が環境でズレる</td><td>演算順・コンパイラ設定・乱数・更新順の再現性。固定小数点も選択肢</td></tr><tr><td>セーブデータ/アセットのバイナリ解析</td><td>16進ダンプ、エンディアン</td></tr><tr><td>日本語ファイル名/テキストの文字化け</td><td>UTF-8/UTF-16</td></tr><tr><td>HDR対応で色が変わった</td><td>色の数値表現・色空間</td></tr></tbody></table><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><ol><li>電卓を使わず 0xDEADBEEF を10進・2進に変換せよ。</li><li>C++で <code>float f = 16777216.0f; f += 1.0f;</code> を実行し、値が増えないことを 確認せよ。なぜ16777216(2^24)なのか、仮数23bitから説明せよ。</li><li><code>float</code>のビットを<code>memcpy</code>で<code>uint32_t</code>に写し、符号・指数・仮数を 自力で分解して表示するプログラムを書け(1.0f, -2.5f, 0.1fで確認)。</li><li>プレイヤー状態(ジャンプ中/無敵/ダッシュ中...)を1つの<code>uint32_t</code>の ビットフラグで管理する関数群(set/clear/test)を書け。</li><li>バイナリエディタ(VSの「バイナリで開く」やHxD)でBMPファイルを開き、 ヘッダの幅・高さをリトルエンディアンで読み取れ。</li></ol><h2 id="おすすめ書籍" tabindex="-1">おすすめ書籍 <a class="header-anchor" href="#おすすめ書籍" aria-label="Permalink to &quot;おすすめ書籍&quot;">​</a></h2><ul><li>『プログラムはなぜ動くのか』矢沢久雄 ── 最初の1冊として最適</li><li>『コンピュータシステムの理論と実装(Nand2Tetris)』── 第2章と併読</li><li>『Land of Lisp』…は不要。寄り道しないこと</li><li>(英語余裕があれば)&quot;Computer Systems: A Programmer&#39;s Perspective (CS:APP)&quot; 第2章 ── 情報表現の決定版。邦訳『コンピュータ・システム』</li></ul><h2 id="おすすめoss" tabindex="-1">おすすめOSS <a class="header-anchor" href="#おすすめoss" aria-label="Permalink to &quot;おすすめOSS&quot;">​</a></h2><ul><li><a href="https://float.exposed" target="_blank" rel="noreferrer">float.exposed</a> / [IEEE754 Visualizer] ── 浮動小数を ビット単位でいじれるWebツール(OSSではないが実験場として最高)</li><li>stb_image (GitHub: nothings/stb) ── 画像=バイト列であることが分かる 1ファイルCライブラリ。読むのは第5章以降でよいが存在を知っておく</li></ul><h2 id="おすすめ動画" tabindex="-1">おすすめ動画 <a class="header-anchor" href="#おすすめ動画" aria-label="Permalink to &quot;おすすめ動画&quot;">​</a></h2><ul><li>Ben Eater &quot;How do computers read binary?&quot; ほか (YouTube, 英語・字幕可)</li><li>「浮動小数点数」で検索して出るCEDECの数値精度系講演</li><li>Computerphile &quot;Floating Point Numbers&quot;</li></ul><h2 id="読むべきソースコード" tabindex="-1">読むべきソースコード <a class="header-anchor" href="#読むべきソースコード" aria-label="Permalink to &quot;読むべきソースコード&quot;">​</a></h2><ul><li>UE5 <code>Engine/Source/Runtime/Core/Public/Math/Float16.h</code> ── 半精度floatの ビット操作の実例(第17章で戻ってきたときに読めるようになっている)</li><li>Quake III <code>q_math.c</code> の高速逆平方根(0x5f3759df)── 「ビットの再解釈」の 最も有名な実例。今は雰囲気だけ眺め、第4章後に再読</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>なぜコンピュータは2進数なのか?(電気的な理由で)</li><li>8bit符号付き整数の範囲が -128〜127 と非対称なのはなぜ?</li><li>floatの <code>0.1f</code> が正確に0.1でないのはなぜ? どう比較すべき?</li><li>座標(100000.0f, 0, 0)付近でキャラが小刻みに震える。原因と対策を述べよ。</li><li>0x41 という1バイトは、整数として・ASCII文字として・何を表すか?</li><li>リトルエンディアンで <code>int 0x12345678</code> はメモリにどう並ぶか?</li></ol><hr><h2 id="この章がゲームのどこで使われているか" tabindex="-1">この章がゲームのどこで使われているか <a class="header-anchor" href="#この章がゲームのどこで使われているか" aria-label="Permalink to &quot;この章がゲームのどこで使われているか&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ボタン → OS → ゲームループ → エンジン → GPU → 画面</span></span>
<span class="line"><span>                  │            │        │</span></span>
<span class="line"><span>                  ▼            ▼        ▼</span></span>
<span class="line"><span>           HP,座標,フラグ   Transform  頂点データ,色</span></span>
<span class="line"><span>           = int/float     = float×16  = float/半精度/sRGB</span></span>
<span class="line"><span>           ─────────── すべて「ビット列+解釈」───────────</span></span>
<span class="line"><span>     セーブデータ・アセットファイル・ネットパケットも全部バイト列</span></span></code></pre></div><h2 id="記述の確認資料" tabindex="-1">記述の確認資料 <a class="header-anchor" href="#記述の確認資料" aria-label="Permalink to &quot;記述の確認資料&quot;">​</a></h2><ul><li><a href="https://www.open-std.org/jtc1/sc22/wg14/www/docs/n1570.pdf" target="_blank" rel="noreferrer">WG14 N1570: C11 committee draft (5.1.2.3, 6.2.4, 6.5, 6.7.2.1)</a></li><li><a href="https://learn.microsoft.com/en-us/dotnet/api/system.single.equals?view=net-10.0" target="_blank" rel="noreferrer">Microsoft: Single.Equals — comparison tolerance</a></li><li><a href="https://learn.microsoft.com/en-us/cpp/build/reference/fp-specify-floating-point-behavior?view=msvc-170" target="_blank" rel="noreferrer">MSVC: /fp floating-point behavior</a></li><li><a href="https://box2d.org/posts/2024/08/determinism/" target="_blank" rel="noreferrer">Box2D: Determinism</a></li></ul>`,30)])])}const f=l(o,[["render",r]]);export{p as __pageData,f as default};
